#[doc = "This object represents an incoming callback query from a callback button in an inline keyboard. If the button that originated the query was attached to a message sent by the bot, the field message will be present. If the button was attached to a message sent via the bot (in inline mode), the field inline_message_id will be present. Exactly one of the fields data or game_short_name will be present."]
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct CallbackQuery {
    #[doc = "Unique identifier for this query"]
    pub id: String,
    #[doc = "Sender"]
    #[serde(rename = "from")]
    pub from_user: User,
    #[doc = "Global identifier, uniquely corresponding to the chat to which the message with the callback button was sent. Useful for high scores in games."]
    pub chat_instance: String,
    #[doc = "Message sent by the bot with the callback button that originated the query"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub message: Option<MaybeInaccessibleMessageUnion>,
    #[doc = "Identifier of the message sent via the bot in inline mode, that originated the query"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub inline_message_id: Option<String>,
    #[doc = "Data associated with the callback button. Be aware that the message originated the query can contain no callback buttons with this data."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub data: Option<String>,
    #[doc = "Short name of a Game to be returned, serves as the unique identifier for the game"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub game_short_name: Option<String>,
    #[serde(flatten, default)]
    pub extra: BTreeMap<String, Value>,
}

impl CollectFiles for CallbackQuery {
    fn collect_files(&self, output: &mut Vec<InputFileUpload>) {
        CollectFiles::collect_files(&self.id, output);
        CollectFiles::collect_files(&self.from_user, output);
        CollectFiles::collect_files(&self.chat_instance, output);
        CollectFiles::collect_files(&self.message, output);
        CollectFiles::collect_files(&self.inline_message_id, output);
        CollectFiles::collect_files(&self.data, output);
        CollectFiles::collect_files(&self.game_short_name, output);
    }
}

impl CallbackQuery {
    pub fn new(id: impl Into<String>, from_user: User, chat_instance: impl Into<String>) -> Self {
        Self {
            id: id.into(),
            from_user,
            chat_instance: chat_instance.into(),
            message: None,
            inline_message_id: None,
            data: None,
            game_short_name: None,
            extra: BTreeMap::new(),
        }
    }

    pub fn message(mut self, value: impl Into<MaybeInaccessibleMessageUnion>) -> Self {
        self.message = Some(value.into());
        self
    }

    pub fn inline_message_id(mut self, value: impl Into<String>) -> Self {
        self.inline_message_id = Some(value.into());
        self
    }

    pub fn data(mut self, value: impl Into<String>) -> Self {
        self.data = Some(value.into());
        self
    }

    pub fn game_short_name(mut self, value: impl Into<String>) -> Self {
        self.game_short_name = Some(value.into());
        self
    }
}

#[doc = "This object represents a chat."]
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Chat {
    #[doc = "Unique identifier for this chat. This number may have more than 32 significant bits and some programming languages may have difficulty/silent defects in interpreting it. But it has at most 52 significant bits, so a signed 64-bit integer or double-precision float type are safe for storing this identifier."]
    pub id: i64,
    #[doc = "Type of the chat, can be either 'private', 'group', 'supergroup' or 'channel'"]
    #[serde(rename = "type")]
    pub kind: String,
    #[doc = "Title, for supergroups, channels and group chats"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,
    #[doc = "Username, for private chats, supergroups and channels if available"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub username: Option<String>,
    #[doc = "First name of the other party in a private chat"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub first_name: Option<String>,
    #[doc = "Last name of the other party in a private chat"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_name: Option<String>,
    #[doc = "True, if the supergroup chat is a forum (has topics enabled)"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub is_forum: Option<bool>,
    #[doc = "True, if the chat is the direct messages chat of a channel"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub is_direct_messages: Option<bool>,
    #[doc = "Identifier of the accent color for the chat name and backgrounds of the chat photo, reply header, and link preview. See accent colors for more details. Returned only in getChat. Always returned in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub accent_color_id: Option<i64>,
    #[doc = "If non-empty, the list of all active chat usernames; for private chats, supergroups and channels. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub active_usernames: Option<Vec<String>>,
    #[doc = "List of available reactions allowed in the chat. If omitted, then all emoji reactions are allowed. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub available_reactions: Option<Vec<ReactionTypeUnion>>,
    #[doc = "Custom emoji identifier of emoji chosen by the chat for the reply header and link preview background. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub background_custom_emoji_id: Option<String>,
    #[doc = "Bio of the other party in a private chat. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bio: Option<String>,
    #[doc = "For private chats, the date of birth of the user. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub birthdate: Option<Birthdate>,
    #[doc = "For private chats with business accounts, the intro of the business. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub business_intro: Option<BusinessIntro>,
    #[doc = "For private chats with business accounts, the location of the business. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub business_location: Option<BusinessLocation>,
    #[doc = "For private chats with business accounts, the opening hours of the business. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub business_opening_hours: Option<BusinessOpeningHours>,
    #[doc = "True, if the bot can change the group sticker set. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub can_set_sticker_set: Option<bool>,
    #[doc = "For supergroups, the name of the group's custom emoji sticker set. Custom emoji from this set can be used by all users and bots in the group. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub custom_emoji_sticker_set_name: Option<String>,
    #[doc = "Description, for groups, supergroups and channel chats. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    #[doc = "Custom emoji identifier of the emoji status of the chat or the other party in a private chat. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub emoji_status_custom_emoji_id: Option<String>,
    #[doc = "Expiration date of the emoji status of the chat or the other party in a private chat, in Unix time, if any. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub emoji_status_expiration_date: Option<i64>,
    #[doc = "True, if aggressive anti-spam checks are enabled in the supergroup. The field is only available to chat administrators. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub has_aggressive_anti_spam_enabled: Option<bool>,
    #[doc = "True, if non-administrators can only get the list of bots and administrators in the chat. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub has_hidden_members: Option<bool>,
    #[doc = "True, if privacy settings of the other party in the private chat allows to use tg://user?id=<user_id> links only in chats with the user. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub has_private_forwards: Option<bool>,
    #[doc = "True, if messages from the chat can't be forwarded to other chats. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub has_protected_content: Option<bool>,
    #[doc = "True, if the privacy settings of the other party restrict sending voice and video note messages in the private chat. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub has_restricted_voice_and_video_messages: Option<bool>,
    #[doc = "True, if new chat members will have access to old messages; available only to chat administrators. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub has_visible_history: Option<bool>,
    #[doc = "Primary invite link, for groups, supergroups and channel chats. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub invite_link: Option<String>,
    #[doc = "True, if all users directly joining the supergroup need to be approved by supergroup administrators. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub join_by_request: Option<bool>,
    #[doc = "True, if users need to join the supergroup before they can send messages. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub join_to_send_messages: Option<bool>,
    #[doc = "Unique identifier for the linked chat, i.e. the discussion group identifier for a channel and vice versa; for supergroups and channel chats. This identifier may be greater than 32 bits and some programming languages may have difficulty/silent defects in interpreting it. But it is smaller than 52 bits, so a signed 64 bit integer or double-precision float type are safe for storing this identifier. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub linked_chat_id: Option<i64>,
    #[doc = "For supergroups, the location to which the supergroup is connected. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub location: Option<ChatLocation>,
    #[doc = "The time after which all messages sent to the chat will be automatically deleted; in seconds. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub message_auto_delete_time: Option<i64>,
    #[doc = "Default chat member permissions, for groups and supergroups. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub permissions: Option<ChatPermissions>,
    #[doc = "For private chats, the personal channel of the user. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub personal_chat: Option<Box<Chat>>,
    #[doc = "Chat photo. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub photo: Option<ChatPhoto>,
    #[doc = "The most recent pinned message (by sending date). Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pinned_message: Option<Box<Message>>,
    #[doc = "Identifier of the accent color for the chat's profile background. See profile accent colors for more details. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub profile_accent_color_id: Option<i64>,
    #[doc = "Custom emoji identifier of the emoji chosen by the chat for its profile background. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub profile_background_custom_emoji_id: Option<String>,
    #[doc = "For supergroups, the minimum allowed delay between consecutive messages sent by each unprivileged user; in seconds. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub slow_mode_delay: Option<i64>,
    #[doc = "For supergroups, name of group sticker set. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub sticker_set_name: Option<String>,
    #[doc = "For supergroups, the minimum number of boosts that a non-administrator user needs to add in order to ignore slow mode and chat permissions. Returned only in getChat."]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub unrestrict_boost_count: Option<i64>,
    #[serde(flatten, default)]
    pub extra: BTreeMap<String, Value>,
}

