#[doc = "This object represents a gift that can be sent by the bot."]
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Gift {
    #[doc = "Unique identifier of the gift"]
    pub id: String,
    #[doc = "The sticker that represents the gift"]
    pub sticker: Sticker,
    #[doc = "The number of Telegram Stars that must be paid to send the sticker"]
    pub star_count: i64,
    #[doc = "The number of Telegram Stars that must be paid to upgrade the gift to a unique one"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub upgrade_star_count: Option<i64>,
    #[doc = "True, if the gift can only be purchased by Telegram Premium subscribers"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub is_premium: Option<bool>,
    #[doc = "True, if the gift can be used (after being upgraded) to customize a user's appearance"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub has_colors: Option<bool>,
    #[doc = "The total number of gifts of this type that can be sent by all users; for limited gifts only"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub total_count: Option<i64>,
    #[doc = "The number of remaining gifts of this type that can be sent by all users; for limited gifts only"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub remaining_count: Option<i64>,
    #[doc = "The total number of gifts of this type that can be sent by the bot; for limited gifts only"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub personal_total_count: Option<i64>,
    #[doc = "The number of remaining gifts of this type that can be sent by the bot; for limited gifts only"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub personal_remaining_count: Option<i64>,
    #[doc = "Background of the gift"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub background: Option<GiftBackground>,
    #[doc = "The total number of different unique gifts that can be obtained by upgrading the gift"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub unique_gift_variant_count: Option<i64>,
    #[doc = "Information about the chat that published the gift"]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub publisher_chat: Option<Box<Chat>>,
    #[serde(flatten, default)]
    pub extra: BTreeMap<String, Value>,
}

