        CollectFiles::collect_files(&self.has_colors, output);
        CollectFiles::collect_files(&self.total_count, output);
        CollectFiles::collect_files(&self.remaining_count, output);
        CollectFiles::collect_files(&self.personal_total_count, output);
        CollectFiles::collect_files(&self.personal_remaining_count, output);
